<?php
function admin_can($module,$action='view'){
 static $cache=[];$key=($_SESSION[USER_AUTH]??'').':'.$module.':'.$action;if(isset($cache[$key]))return $cache[$key];if(empty($_SESSION[USER_AUTH]))return false;$u=sc_query('SELECT id,user_group FROM users WHERE userid=? AND is_active=1 AND is_deleted=0','s',[$_SESSION[USER_AUTH]])->get_result()->fetch_assoc();if(!$u)return false;if((int)$u['user_group']===1)return $cache[$key]=true;$slug=$module.':'.$action;$row=sc_query('SELECT p.id FROM permissions p LEFT JOIN user_permissions up ON up.permission_id=p.id AND up.user_id=? AND up.allow=1 LEFT JOIN group_permissions gp ON gp.permission_id=p.id AND gp.group_id=? AND gp.allow=1 WHERE p.slug=? AND (up.user_id IS NOT NULL OR gp.group_id IS NOT NULL) LIMIT 1','iis',[$u['id'],$u['user_group'],$slug])->get_result()->fetch_assoc();return $cache[$key]=(bool)$row;
}
function admin_console_open($title){echo '<!doctype html><html lang="en" class="light-style layout-menu-fixed"><head>'.loadAdminMetaData().loadAdminTitleAndFavicon($title).loadAdminStyleSheets().loadAdminScripts().getAjaxRequester().'</head><body><div class="layout-wrapper layout-content-navbar"><div class="layout-container">';loadAdminSidebar($title);echo '<div class="layout-page">';loadAdminNavbar();echo '<div class="content-wrapper"><main class="container-xxl container-p-y"><h1 class="h3">'.sc_e($title).'</h1>';}
function admin_console_close(){echo '</main>';loadAdminFooter();echo '</div></div></div><div class="layout-overlay layout-menu-toggle"></div></div>'.loadAdminFooterScripts().'</body></html>';}
function admin_search_results($term){
 $term=mb_substr(trim($term),0,100);if(mb_strlen($term)<2)return [];$needle='%'.addcslashes($term,'%_\\').'%';$out=[];
 $features=[['Products','product','products/'],['Product categories','product_category','product-categories/'],['Inventory and stock','inventory','inventory/'],['Online users customers','sale','online-users/'],['Online orders purchases','sale','online-orders/'],['Patients','patient','patients/'],['Referrals referring doctor recommendations','consultation','consultations/'],['Consultations reports documents','consultation','consultations/'],['Invoices documents','invoice','invoices/'],['Users staff','user','users/'],['Pages content','pages','pages/'],['Treatment sites clinics','treatment_site','treatment-sites/'],['User groups permissions','user_group','user-groups/'],['Support tickets','support','support/'],['Festive season Diwali Holi Eid Christmas New Year','app_settings','festivals/'],['Settings','app_settings','settings/'],['Appearance themes colours background','dashboard','appearance/']];foreach($features as [$label,$permission,$path])if(($permission==='dashboard'||admin_can($permission))&&stripos($label,$term)!==false)$out[]=['type'=>'Feature','label'=>$label,'detail'=>'Open section','url'=>sc_url('admin/'.$path)];
 $sources=[
 ['Products','product','SELECT id,product_name label,slug detail FROM products WHERE is_active=1 AND is_deleted=0 AND (product_name LIKE ? OR slug LIKE ?)','products/'],
 ['Online users','sale',"SELECT id,CONCAT(first_name,' ',last_name) label,email detail FROM online_users WHERE is_deleted=0 AND (CONCAT(first_name,' ',last_name) LIKE ? OR email LIKE ?)",'online-users/'],
 ['Online orders','sale','SELECT id,order_number label,status detail FROM web_orders WHERE (order_number LIKE ? OR status LIKE ?)','online-orders/'],
 ['Patients','patient',"SELECT id,CONCAT(first_name,' ',COALESCE(last_name,'')) label,CONCAT('PI-',patientid,' / ',uhid) detail FROM patients WHERE is_active=1 AND is_deleted=0 AND (CONCAT(first_name,' ',COALESCE(last_name,'')) LIKE ? OR uhid LIKE ? OR phone LIKE ? OR CAST(patientid AS CHAR) LIKE ?)",'patients/'],
 ['Invoices','invoice',"SELECT id,CONCAT('Invoice ',customerinvoiceuid) label,customer_name detail FROM customer_invoices WHERE is_active=1 AND is_deleted=0 AND (customer_name LIKE ? OR CAST(customerinvoiceuid AS CHAR) LIKE ?)",'invoices/'],
 ['Pages','pages','SELECT page_id id,page_title label,slug detail FROM pages WHERE is_deleted=0 AND is_trashed=0 AND (page_title LIKE ? OR page_content LIKE ?)','pages/'],
 ];
 $sources[]=['Product categories','product_category','SELECT id,category_name label,slug detail FROM product_categories WHERE is_active=1 AND is_deleted=0 AND (category_name LIKE ? OR slug LIKE ?)','product-categories/'];
 $sources[]=['Treatment sites','treatment_site','SELECT id,site_name label,site_id detail FROM sites WHERE is_active=1 AND is_deleted=0 AND (site_name LIKE ? OR site_id LIKE ?)','treatment-sites/'];
 $sources[]=['Sales','sale',"SELECT id,CONCAT('Sale SI-',saleid) label,CONCAT('Patient ',patient_id) detail FROM sales WHERE is_active=1 AND is_deleted=0 AND (CAST(saleid AS CHAR) LIKE ? OR CAST(patient_id AS CHAR) LIKE ?)",'sales/'];
 // Staff search follows the existing staff-module visibility rules.
 $group=(int)userVariable('user_group');$staffScope=$group===1?'':($group===2?' AND user_group<>1':' AND user_group NOT IN (1,2)');$sources[]=['Staff','user',"SELECT id,CONCAT(first_name,' ',last_name) label,userid detail FROM users WHERE is_active=1 AND is_deleted=0 $staffScope AND (CONCAT(first_name,' ',last_name) LIKE ? OR userid LIKE ?)",'users/'];
 $scope=in_array($group,[1,2],true)?'':' AND c.site_id='.(int)userVariable('treatment_site');$sources[]=['Consultation documents','consultation',"SELECT c.id,CONCAT('Consultation CI-',c.id) label,CONCAT(p.first_name,' ',COALESCE(p.last_name,'')) detail FROM consultations c LEFT JOIN patients p ON p.id=c.patient_id WHERE c.is_active=1 AND c.is_deleted=0 $scope AND (CAST(c.id AS CHAR) LIKE ? OR p.first_name LIKE ? OR p.last_name LIKE ?)",'consultations/'];
 foreach($sources as [$type,$permission,$sql,$path]){if(!admin_can($permission))continue;$n=substr_count($sql,'?');$rows=sc_query($sql.' ORDER BY id DESC LIMIT 8',str_repeat('s',$n),array_fill(0,$n,$needle))->get_result();while($r=$rows->fetch_assoc())$out[]=['type'=>$type,'label'=>$r['label'],'detail'=>$r['detail'],'url'=>sc_url('admin/'.$path.'?id='.(int)$r['id'].'&view')];}
 return $out;
}
